cat > /tmp/t.mjs <<'EOF'
import { createPushGate } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-sonnet/work/courier-inv-g2-1/bot.mjs";
import assert from "node:assert";
const u = { id:"u1", timeZone:"Asia/Tokyo", quietStart:"22:00", quietEnd:"07:00", dailyCap:3 };
const g = createPushGate();
// Tokyo 12:00 = 03:00Z
const d = (s)=>new Date(s);
assert.deepEqual(g.attempt(u,d("2026-03-10T03:00:00Z")),{allowed:true,reason:null});
// Tokyo 22:00 -> quiet; 06:59 quiet; 07:00 ok
assert.equal(g.attempt(u,d("2026-03-10T13:00:00Z")).reason,"quiet_hours");
assert.equal(g.attempt(u,d("2026-03-10T21:59:00Z")).reason,"quiet_hours");
assert.equal(g.attempt(u,d("2026-03-10T22:00:00Z")).allowed,true); // 07:00 Tokyo, 2nd
assert.equal(g.attempt(u,d("2026-03-10T23:00:00Z")).allowed,true); // 3rd (same Tokyo day 03-11? 08:00 on 03-11 -> new day)
// cap: Tokyo 03-10 has 1 push; add 2 more then block
assert.equal(g.attempt(u,d("2026-03-10T04:00:00Z")).allowed,true);
assert.equal(g.attempt(u,d("2026-03-10T05:00:00Z")).allowed,true);
assert.equal(g.attempt(u,d("2026-03-10T06:00:00Z")).reason,"daily_cap_reached");
// local midnight rollover: 14:59Z = 23:59 Tokyo quiet; next day 15:00Z quiet; pick 22:00Z (07:00 03-11) has 2 already -> one more ok, then block
assert.equal(g.attempt(u,d("2026-03-10T22:30:00Z")).allowed,true);
assert.equal(g.attempt(u,d("2026-03-10T23:30:00Z")).reason,"daily_cap_reached");
// other user independent, and another gate independent
assert.equal(g.attempt({...u,id:"u2"},d("2026-03-10T03:00:00Z")).allowed,true);
assert.equal(createPushGate().attempt(u,d("2026-03-10T06:00:00Z")).allowed,true);
// UTC midnight must not reset a Los Angeles day: LA 17:00-23:00 on 03-10 (PDT? DST begins 03-08 so UTC-7)
const la={id:"l",timeZone:"America/Los_Angeles",quietStart:"22:00",quietEnd:"07:00",dailyCap:2};
const g2=createPushGate();
assert.equal(g2.attempt(la,d("2026-03-11T00:00:00Z")).allowed,true); // 17:00 LA
assert.equal(g2.attempt(la,d("2026-03-11T04:00:00Z")).allowed,true); // 21:00 LA, after UTC midnight
assert.equal(g2.attempt(la,d("2026-03-11T05:00:00Z")).reason,"quiet_hours"); // 22:00
assert.equal(g2.attempt(la,d("2026-03-11T06:30:00Z")).reason,"quiet_hours");
assert.equal(g2.attempt(la,d("2026-03-11T15:00:00Z")).allowed,true); // 08:00 LA next day, new day
// same-day window, cap 0, bad input
const day={...la,id:"d",quietStart:"13:00",quietEnd:"14:00"};
assert.equal(createPushGate().attempt(day,d("2026-03-11T20:30:00Z")).reason,"quiet_hours");
assert.equal(createPushGate().attempt({...la,dailyCap:0},d("2026-03-11T00:00:00Z")).reason,"daily_cap_reached");
assert.equal(createPushGate().attempt({...la,timeZone:"Nope/Zone"},d("2026-03-11T00:00:00Z")).reason,"invalid_time_zone");
console.log("ok");
EOF
node /tmp/t.mjs
